#!/usr/bin/env bash\n\n# Configuration\n# -------------\nSCRIPT_NAME=\"$(basename \"$0\")\"\nSCRIPT_DIR=\"$(cd \"$(dirname \"$0\")\" && pwd)\"\nREPO_ROOT_DIR=\"$(cd \"${SCRIPT_DIR}/..\" && pwd)\"\nSCRIPT_ENV_FILE=\"\"\nUSE_CACHE_BUILD=\"${USE_CACHE_BUILD:-1}\"             # set to 1 to enable buildx inline cache\nUSE_BUILDX_COMPRESSED_BUILD=\"${USE_BUILDX_COMPRESSED_BUILD:-0}\" # set to 0 to use plain docker compose build\nKEEP_IMAGES=\"${KEEP_IMAGES:-0}\"                     # set to 1 to keep existing images\nSTART_CONTAINERS=\"${START_CONTAINERS:-1}\"            # set to 0 to skip `docker compose up -d`\nBUILDX_COMPRESSED_BUILD_SCRIPT_RELATIVE_PATH=\"${BUILDX_COMPRESSED_BUILD_SCRIPT_RELATIVE_PATH:-installation/docker_buildx_compressed_push.sh}\"\nINSTALLATION_AUTOMATION_MODE=\"${INSTALLATION_AUTOMATION_MODE:-0}\" # set to 1 to run fully non-interactive (no /dev/tty prompts)\nCOMPOSE_UP_RETRIES=\"${COMPOSE_UP_RETRIES:-3}\"\nCOMPOSE_UP_RETRY_DELAY_SECONDS=\"${COMPOSE_UP_RETRY_DELAY_SECONDS:-5}\"\nOMERO_SERVER_UID=\"${OMERO_SERVER_UID:-}\"\nOMERO_SERVER_GID=\"${OMERO_SERVER_GID:-}\"\nOMERO_WEB_UID=\"${OMERO_WEB_UID:-}\"\nOMERO_WEB_GID=\"${OMERO_WEB_GID:-}\"\nPROMETHEUS_UID=\"${PROMETHEUS_UID:-}\"\nPROMETHEUS_GID=\"${PROMETHEUS_GID:-}\"\nGRAFANA_UID=\"${GRAFANA_UID:-}\"\nGRAFANA_GID=\"${GRAFANA_GID:-}\"\nLOKI_UID=\"${LOKI_UID:-}\"\nLOKI_GID=\"${LOKI_GID:-}\"\nDATABASE_UID=\"${DATABASE_UID:-}\"\nDATABASE_GID=\"${DATABASE_GID:-}\"\nDATABASE_PLUGIN_UID=\"${DATABASE_PLUGIN_UID:-}\"\nDATABASE_PLUGIN_GID=\"${DATABASE_PLUGIN_GID:-}\"\nCROWDSEC_UID=\"${CROWDSEC_UID:-}\"\nCROWDSEC_GID=\"${CROWDSEC_GID:-}\"\nOMERO_SERVER_ENV_FILE=\"${REPO_ROOT_DIR}/env/omeroserver.env\"\n\n# Allow override, but default to the repo's current image names (adjust via env vars if you rename them in compose)\nOMERO_SERVER_IMAGE=\"${OMERO_SERVER_IMAGE:-omeroserver:custom}\"\nOMERO_WEB_IMAGE=\"${OMERO_WEB_IMAGE:-omeroweb:custom}\"\nPROMETHEUS_IMAGE=\"${PROMETHEUS_IMAGE:-}\"\nGRAFANA_IMAGE=\"${GRAFANA_IMAGE:-}\"\nLOKI_IMAGE=\"${LOKI_IMAGE:-}\"\nDATABASE_IMAGE=\"${DATABASE_IMAGE:-}\"\nDATABASE_PLUGIN_IMAGE=\"${DATABASE_PLUGIN_IMAGE:-}\"\nCROWDSEC_IMAGE=\"${CROWDSEC_IMAGE:-crowdsec:custom}\"\n\nset -euo pipefail\n\n\nload_installation_paths_env() {\n    local env_file_path=\"${1:?BUG: load_installation_paths_env requires a path}\"\n    local env_line\n    local env_key\n    local env_value\n\n    if [ ! -r \"${env_file_path}\" ]; then\n        echo \"ERROR: Installation paths file is missing or unreadable: ${env_file_path}\" >&2\n        return 1\n    fi\n\n    while IFS= read -r env_line || [ -n \"${env_line}\" ]; do\n        case \"${env_line}\" in\n            ''|'#'*)\n                continue\n                ;;\n            [A-Za-z_]*=*)\n                env_key=\"${env_line%%=*}\"\n                env_value=\"${env_line#*=}\"\n                eval \"${env_key}=\\\"${env_value}\\\"\"\n                ;;\n            *)\n                ;;\n        esac\n    done < \"${env_file_path}\"\n}\n\nload_secrets_env() {\n    local secrets_env_file=\"${1:?BUG: load_secrets_env requires a path}\"\n\n    if [ ! -r \"${secrets_env_file}\" ]; then\n        echo \"ERROR: Secrets env file is missing or unreadable: ${secrets_env_file}\" >&2\n        echo \"ERROR: Create it from env/omero_secrets_example.env (copy → env/omero_secrets.env) and set real values.\" >&2\n        return 1\n    fi\n\n    set -a\n    load_installation_paths_env \"${secrets_env_file}\"\n    set +a\n}\n\n\nbootstrap_env_files_from_examples() {\n    local env_dir=\"${REPO_ROOT_DIR}/env\"\n    local example_file actual_file\n\n    if [ ! -d \"${env_dir}\" ]; then\n        return 0\n    fi\n\n    for example_file in \"${env_dir}\"/*_example.env; do\n        [ -f \"${example_file}\" ] || continue\n\n        # IMPORTANT:\n        # Secrets MUST NEVER be auto-created by automation.\n        # The user is the sole creator of env/omero_secrets.env.\n        if [ \"$(basename \"${example_file}\")\" = \"omero_secrets_example.env\" ]; then\n            continue\n        fi\n\n        # Derive the actual filename: foo_example.env → foo.env\n        actual_file=\"${example_file%_example.env}.env\"\n        if [ ! -f \"${actual_file}\" ]; then\n            echo \"First-time setup: creating ${actual_file} from $(basename \"${example_file}\")\"\n            cp \"${example_file}\" \"${actual_file}\"\n        fi\n    done\n}\n\nresolve_script_env_file() {\n    local default_env_file=\"${REPO_ROOT_DIR}/installation_paths.env\"\n\n    bootstrap_env_files_from_examples\n\n    if [ ! -f \"${default_env_file}\" ]; then\n        echo \"ERROR: Missing required installation paths file: ${default_env_file}\" >&2\n        echo \"ERROR: Create it manually from installation_paths_example.env and set your own paths before rerunning.\" >&2\n        return 1\n    fi\n\n    SCRIPT_ENV_FILE=\"${default_env_file}\"\n}\n\n\n# Bash requirement (warning)\n# --------------------------\nif [ -z \"${BASH_VERSION:-}\" ]; then\n    echo \"ERROR: This script MUST be run with bash.\" >&2\n    exit 1\nfi\n\nif ! resolve_script_env_file; then\n    exit 1\nfi\n\nif ! load_installation_paths_env \"${SCRIPT_ENV_FILE}\"; then\n    exit 1\nfi\n\n\nSECRETS_ENV_FILE=\"${REPO_ROOT_DIR}/env/omero_secrets.env\"\nif ! load_secrets_env \"${SECRETS_ENV_FILE}\"; then\n    exit 1\nfi\n\nif [ -r \"${OMERO_SERVER_ENV_FILE}\" ]; then\n    set -a\n    load_installation_paths_env \"${OMERO_SERVER_ENV_FILE}\"\n    set +a\nfi\n\nrequire_nonempty_config_var() {\n    local variable_name=\"$1\"\n    local variable_source=\"$2\"\n    local variable_value=\"${!variable_name:-}\"\n\n    if [ -z \"${variable_value}\" ]; then\n        echo \"ERROR: Missing required configuration variable ${variable_name} in ${variable_source}\" >&2\n        return 1\n    fi\n\n    return 0\n}\n\nrequire_path_config_var() {\n    local variable_name=\"$1\"\n    local variable_source=\"$2\"\n    local variable_value=\"${!variable_name:-}\"\n\n    if ! require_nonempty_config_var \"${variable_name}\" \"${variable_source}\"; then\n        return 1\n    fi\n\n    if ! is_valid_linux_path \"${variable_value}\"; then\n        echo \"ERROR: ${variable_name} must be a valid absolute Linux path: ${variable_value}\" >&2\n        return 1\n    fi\n\n    return 0\n}\n\nvalidate_retry_config() {\n    if ! [[ \"${COMPOSE_UP_RETRIES}\" =~ ^[0-9]+$ ]] || [ \"${COMPOSE_UP_RETRIES}\" -lt 1 ]; then\n        echo \"ERROR: COMPOSE_UP_RETRIES must be an integer >= 1. Got: ${COMPOSE_UP_RETRIES}\" >&2\n        return 1\n    fi\n\n    if ! [[ \"${COMPOSE_UP_RETRY_DELAY_SECONDS}\" =~ ^[0-9]+$ ]]; then\n        echo \"ERROR: COMPOSE_UP_RETRY_DELAY_SECONDS must be an integer >= 0. Got: ${COMPOSE_UP_RETRY_DELAY_SECONDS}\" >&2\n        return 1\n    fi\n\n    return 0\n}\n\nvalidate_toggle_config() {\n    local variable_name=\"${1:?BUG: validate_toggle_config requires variable name}\"\n    local variable_value=\"${2:-}\"\n\n    if [ \"${variable_value}\" != \"0\" ] && [ \"${variable_value}\" != \"1\" ]; then\n        echo \"ERROR: ${variable_name} must be 0 or 1. Got: ${variable_value}\" >&2\n        return 1\n    fi\n\n    return 0\n}\n\nresolve_buildx_inline_cache_setting() {\n    if [ -n \"${DOCKER_BUILD_INLINE_CACHE:-}\" ]; then\n        printf '%s' \"${DOCKER_BUILD_INLINE_CACHE}\"\n        return 0\n    fi\n\n    printf '%s' \"${USE_CACHE_BUILD}\"\n    return 0\n}\n\n# ---------------------------------------------------------------------------\n# run_image_build\n#\n# Buildx compressed build (zstd) is always used - fully automatic.\n# Cache is controlled by USE_CACHE_BUILD (from the \"Use cache?\" prompt),\n# which applies to both buildx inline cache and docker build cache.\n# ---------------------------------------------------------------------------\nrun_image_build() {\n    local inline_cache_setting=\"\"\n    local buildx_helper_path=\"${OMERO_INSTALLATION_PATH%/}/${BUILDX_COMPRESSED_BUILD_SCRIPT_RELATIVE_PATH}\"\n\n    if [ \"${USE_BUILDX_COMPRESSED_BUILD}\" = \"0\" ]; then\n        echo \"Building OMERO images via docker compose build workflow...\"\n        echo \"  Compose file   : ${COMPOSE_FILE}\"\n        echo \"  Cache enabled  : ${USE_CACHE_BUILD}\"\n\n        if [ \"${USE_CACHE_BUILD}\" = \"0\" ]; then\n            compose_with_installation_env \"${COMPOSE_FILE}\" build --no-cache\n        else\n            compose_with_installation_env \"${COMPOSE_FILE}\" build\n        fi\n        return 0\n    fi\n\n    if [ ! -x \"${buildx_helper_path}\" ]; then\n        echo \"ERROR: Buildx compression helper is missing or not executable: ${buildx_helper_path}\" >&2\n        echo \"ERROR: Re-run the pull/update script and ensure installation/docker_buildx_compressed_push.sh exists.\" >&2\n        return 1\n    fi\n\n    inline_cache_setting=\"$(resolve_buildx_inline_cache_setting)\"\n\n    echo \"Building OMERO images via Buildx compressed (zstd) workflow...\"\n    echo \"  Helper script : ${buildx_helper_path}\"\n    echo \"  Cache enabled : ${inline_cache_setting}\"\n\n    # Derive no-cache flag: if cache is disabled (0), also disable docker layer cache\n    local no_cache_setting=\"0\"\n    if [ \"${inline_cache_setting}\" = \"0\" ]; then\n        no_cache_setting=\"1\"\n    fi\n\n    COMPOSE_FILE=\"${COMPOSE_FILE}\" \\\n        DOCKER_BUILD_INLINE_CACHE=\"${inline_cache_setting}\" \\\n        DOCKER_BUILD_NO_CACHE=\"${no_cache_setting}\" \\\n        DOCKER_BUILD_LOCAL_CACHE_ENABLED=\"${DOCKER_BUILD_LOCAL_CACHE_ENABLED:-1}\" \\\n        DOCKER_BUILD_LOCAL_CACHE_MODE=\"${DOCKER_BUILD_LOCAL_CACHE_MODE:-min}\" \\\n        \"${buildx_helper_path}\"\n    return $?\n}\n\nresolve_buildx_local_cache_dir() {\n    if [ -n \"${BUILDX_DATA_PATH:-}\" ]; then\n        printf '%s' \"${BUILDX_DATA_PATH}\"\n        return 0\n    fi\n\n    if [ -n \"${OMERO_DATA_PATH:-}\" ]; then\n        printf '%s' \"${OMERO_DATA_PATH%/}/buildx_cache\"\n        return 0\n    fi\n\n    return 1\n}\n\ncleanup_local_build_cache_if_disabled() {\n    local buildx_local_cache_dir=\"\"\n\n    if [ \"${USE_CACHE_BUILD}\" != \"0\" ]; then\n        return 0\n    fi\n\n    echo \"Build cache is disabled; cleaning local build cache before rebuild...\"\n\n    if docker builder prune --help >/dev/null 2>&1; then\n        if ! docker builder prune -a -f >/dev/null; then\n            echo \"ERROR: Failed to clean docker builder cache while USE_CACHE_BUILD=0.\" >&2\n            return 1\n        fi\n        echo \"Removed docker builder cache.\"\n    else\n        echo \"WARNING: docker builder prune is unavailable; skipping docker builder cache cleanup.\"\n    fi\n\n    if [ \"${USE_BUILDX_COMPRESSED_BUILD}\" = \"1\" ]; then\n        if ! buildx_local_cache_dir=\"$(resolve_buildx_local_cache_dir)\"; then\n            echo \"ERROR: Buildx cache cleanup requested but no cache path could be resolved (BUILDX_DATA_PATH and OMERO_DATA_PATH are both unset).\" >&2\n            return 1\n        fi\n\n        if [ -d \"${buildx_local_cache_dir}\" ]; then\n            if ! rm -rf \"${buildx_local_cache_dir}\"; then\n                echo \"ERROR: Failed to remove Buildx local cache directory: ${buildx_local_cache_dir}\" >&2\n                return 1\n            fi\n            echo \"Removed Buildx local cache directory: ${buildx_local_cache_dir}\"\n        else\n            echo \"Buildx local cache directory not present, nothing to remove: ${buildx_local_cache_dir}\"\n        fi\n    fi\n\n    return 0\n}\n\ncompose_with_installation_env() {\n    local compose_file=\"$1\"\n    shift\n\n    docker compose \\\n        --project-directory \"${OMERO_INSTALLATION_PATH%/}\" \\\n        -f \"${compose_file}\" \\\n        \"$@\"\n}\n\ncompose_images_with_installation_env() {\n    local compose_file=\"$1\"\n\n    compose_with_installation_env \"${compose_file}\" config --images 2>/dev/null || true\n}\n\nexport_compose_interpolation_env() {\n    local env_var_name=\"\"\n    local required_compose_env_vars=(\n        OMERO_INSTALLATION_PATH\n        OMERO_DATABASE_PATH\n        OMERO_PLUGIN_DATABASE_PATH\n        OMERO_DATA_PATH\n        OMERO_USER_DATA_PATH\n        OMERO_UPLOAD_PATH\n        OMERO_SERVER_VAR_PATH\n        OMERO_WEB_VAR_PATH\n        OMERO_SERVER_LOGS_PATH\n        OMERO_WEB_LOGS_PATH\n        OMERO_WEB_SUPERVISOR_LOGS_PATH\n        PORTAINER_DATA_PATH\n        PROMETHEUS_DATA_PATH\n        GRAFANA_DATA_PATH\n        LOKI_DATA_PATH\n        PG_MAINTENANCE_DATA_PATH\n        BUILDX_DATA_PATH\n        NODE_EXPORTER_TEXTFILE_PATH\n        CROWDSEC_DB_PATH\n        CROWDSEC_CONFIG_PATH\n        OMERO_DB_PASS\n        OMP_PLUGIN_DB_PASS\n    )\n\n    for env_var_name in \"${required_compose_env_vars[@]}\"; do\n        if [ -z \"${!env_var_name:-}\" ]; then\n            echo \"ERROR: Missing required docker compose interpolation variable: ${env_var_name}\" >&2\n            return 1\n        fi\n\n        export \"${env_var_name}=${!env_var_name}\"\n    done\n\n\n    return 0\n}\n\nvalidate_numeric_id() {\n    local id_label=\"$1\"\n    local id_value=\"$2\"\n\n    if ! [[ \"${id_value}\" =~ ^[0-9]+$ ]]; then\n        echo \"ERROR: ${id_label} must be a numeric ID. Got: ${id_value}\" >&2\n        return 1\n    fi\n\n    return 0\n}\n\nprobe_image_user_id() {\n    local image_name=\"$1\"\n    local probe_name=\"omero-install-probe-user-${RANDOM}\"\n    local result\n    result=$(docker run --rm --name \"${probe_name}\" --entrypoint id \"${image_name}\" -u 2>/dev/null || true)\n    docker rm -f \"${probe_name}\" >/dev/null 2>&1 || true\n    echo \"${result}\"\n}\n\nprobe_image_group_id() {\n    local image_name=\"$1\"\n    local probe_name=\"omero-install-probe-group-${RANDOM}\"\n    local result\n    result=$(docker run --rm --name \"${probe_name}\" --entrypoint id \"${image_name}\" -g 2>/dev/null || true)\n    docker rm -f \"${probe_name}\" >/dev/null 2>&1 || true\n    echo \"${result}\"\n}\n\nprobe_image_user_and_group() {\n    local image_name=\"$1\"\n    local probe_name=\"omero-install-probe-users-${RANDOM}\"\n    local result\n    result=$(docker run --rm --name \"${probe_name}\" --entrypoint id \"${image_name}\" -u -g 2>/dev/null | awk '{print $1\":\"$2}' || true)\n    docker rm -f \"${probe_name}\" >/dev/null 2>&1 || true\n    echo \"${result}\"\n}\n\nis_valid_linux_path() {\n    local path=\"$1\"\n    if [[ -z \"$path\" || \"$path\" != /* || \"$path\" == *\"\\0\"* ]]; then\n        return 1\n    fi\n    return 0\n}\n\nresolve_uid_gid() {\n    local service_label=\"$1\"\n    local user_override=\"$2\"\n    local group_override=\"$3\"\n    local image_name=\"$4\"\n    local fallback_uid=\"$5\"\n    local fallback_gid=\"$6\"\n\n    local final_uid=\"${user_override}\"\n    local final_gid=\"${group_override}\"\n\n    if [ -z \"${final_uid}\" ] || [ -z \"${final_gid}\" ]; then\n        local probe_result=\"\"\n        if [ -n \"${image_name}\" ] && docker image inspect \"${image_name}\" >/dev/null 2>&1; then\n            probe_result=\"$(probe_image_user_and_group \"${image_name}\")\"\n        fi\n        \n        if [ -n \"${probe_result}\" ] && [[ \"${probe_result}\" == *:* ]]; then\n            if [ -z \"${final_uid}\" ]; then final_uid=\"${probe_result%%:*}\"; fi\n            if [ -z \"${final_gid}\" ]; then final_gid=\"${probe_result##*:}\"; fi\n        else\n            if [ -z \"${final_uid}\" ]; then final_uid=\"${fallback_uid}\"; fi\n            if [ -z \"${final_gid}\" ]; then final_gid=\"${fallback_gid}\"; fi\n        fi\n    fi\n    \n    echo \"${final_uid}:${final_gid}\"\n}\n\n# ---------------------------------------------------------------------------\n# File and directory setup\n# ---------------------------------------------------------------------------\nensure_directory() {\n    local dir_path=\"$1\"\n    local uid=\"$2\"\n    local gid=\"$3\"\n    local perms=\"${4:-755}\"\n    local create_msg=\"${5:-Creating directory}\"\n\n    if [ ! -d \"${dir_path}\" ]; then\n        echo \"${create_msg}: ${dir_path} (uid:${uid}, gid:${gid})\"\n        if ! mkdir -p \"${dir_path}\"; then\n            echo \"ERROR: Failed to create directory ${dir_path}\" >&2\n            return 1\n        fi\n        chown \"${uid}:${gid}\" \"${dir_path}\"\n        chmod \"${perms}\" \"${dir_path}\"\n    else\n        local current_uid current_gid current_perms\n        current_uid=$(stat -c '%u' \"${dir_path}\")\n        current_gid=$(stat -c '%g' \"${dir_path}\")\n        current_perms=$(stat -c '%a' \"${dir_path}\")\n        \n        if [ \"${current_uid}\" != \"${uid}\" ] || [ \"${current_gid}\" != \"${gid}\" ]; then\n            echo \"Updating ownership for ${dir_path} from ${current_uid}:${current_gid} to ${uid}:${gid}\"\n            chown \"${uid}:${gid}\" \"${dir_path}\"\n        fi\n        \n        # Optional: update permissions if they are too restrictive (e.g., missing execute)\n        # But generally we want to be cautious about overriding user-set permissions on existing dirs\n    fi\n    return 0\n}\n\nensure_file() {\n    local file_path=\"$1\"\n    local uid=\"$2\"\n    local gid=\"$3\"\n    local perms=\"${4:-644}\"\n    local create_msg=\"${5:-Creating file}\"\n\n    if [ ! -f \"${file_path}\" ]; then\n        echo \"${create_msg}: ${file_path} (uid:${uid}, gid:${gid})\"\n        # Ensure parent dir exists\n        mkdir -p \"$(dirname \"${file_path}\")\"\n        if ! touch \"${file_path}\"; then\n            echo \"ERROR: Failed to create file ${file_path}\" >&2\n            return 1\n        fi\n        chown \"${uid}:${gid}\" \"${file_path}\"\n        chmod \"${perms}\" \"${file_path}\"\n    else\n        local current_uid current_gid\n        current_uid=$(stat -c '%u' \"${file_path}\")\n        current_gid=$(stat -c '%g' \"${file_path}\")\n        \n        if [ \"${current_uid}\" != \"${uid}\" ] || [ \"${current_gid}\" != \"${gid}\" ]; then\n            echo \"Updating ownership for ${file_path} from ${current_uid}:${current_gid} to ${uid}:${gid}\"\n            chown \"${uid}:${gid}\" \"${file_path}\"\n        fi\n    fi\n    return 0\n}\n\nsetup_directories() {\n    echo \"Setting up storage directories with proper permissions...\"\n    \n    # Resolve UIDs/GIDs\n    local omero_server_id omero_web_id prometheus_id grafana_id loki_id db_id plugin_db_id crowdsec_id\n    \n    omero_server_id=$(resolve_uid_gid \"OMERO.server\" \"${OMERO_SERVER_UID}\" \"${OMERO_SERVER_GID}\" \"${OMERO_SERVER_IMAGE}\" \"1000\" \"1000\")\n    omero_web_id=$(resolve_uid_gid \"OMERO.web\" \"${OMERO_WEB_UID}\" \"${OMERO_WEB_GID}\" \"${OMERO_WEB_IMAGE}\" \"1000\" \"1000\")\n    prometheus_id=$(resolve_uid_gid \"Prometheus\" \"${PROMETHEUS_UID}\" \"${PROMETHEUS_GID}\" \"${PROMETHEUS_IMAGE}\" \"65534\" \"65534\")\n    grafana_id=$(resolve_uid_gid \"Grafana\" \"${GRAFANA_UID}\" \"${GRAFANA_GID}\" \"${GRAFANA_IMAGE}\" \"472\" \"472\")\n    loki_id=$(resolve_uid_gid \"Loki\" \"${LOKI_UID}\" \"${LOKI_GID}\" \"${LOKI_IMAGE}\" \"10001\" \"10001\")\n    db_id=$(resolve_uid_gid \"Database\" \"${DATABASE_UID}\" \"${DATABASE_GID}\" \"${DATABASE_IMAGE}\" \"999\" \"999\")\n    plugin_db_id=$(resolve_uid_gid \"Plugin Database\" \"${DATABASE_PLUGIN_UID}\" \"${DATABASE_PLUGIN_GID}\" \"${DATABASE_PLUGIN_IMAGE}\" \"999\" \"999\")\n    crowdsec_id=$(resolve_uid_gid \"CrowdSec\" \"${CROWDSEC_UID}\" \"${CROWDSEC_GID}\" \"${CROWDSEC_IMAGE}\" \"0\" \"0\")\n\n    # OMERO.server\n    ensure_directory \"${OMERO_DATA_PATH}\" \"${omero_server_id%%:*}\" \"${omero_server_id##*:}\" 755 \"Creating OMERO binary data dir\"\n    ensure_directory \"${OMERO_SERVER_VAR_PATH}\" \"${omero_server_id%%:*}\" \"${omero_server_id##*:}\" 755 \"Creating OMERO.server var dir\"\n    ensure_directory \"${OMERO_SERVER_LOGS_PATH}\" \"${omero_server_id%%:*}\" \"${omero_server_id##*:}\" 755 \"Creating OMERO.server logs dir\"\n    \n    # Handle buildx cache dir if it exists inside OMERO_DATA_PATH (must be accessible to buildx)\n    if [ -n \"${BUILDX_DATA_PATH:-}\" ]; then\n        ensure_directory \"${BUILDX_DATA_PATH}\" \"0\" \"0\" 755 \"Creating Buildx cache dir\"\n    elif [ -n \"${OMERO_DATA_PATH:-}\" ]; then\n        # The fallback local cache dir\n        ensure_directory \"${OMERO_DATA_PATH%/}/buildx_cache\" \"0\" \"0\" 755 \"Creating Buildx cache dir\"\n    fi\n\n    # OMERO.web\n    ensure_directory \"${OMERO_WEB_VAR_PATH}\" \"${omero_web_id%%:*}\" \"${omero_web_id##*:}\" 755 \"Creating OMERO.web var dir\"\n    ensure_directory \"${OMERO_WEB_LOGS_PATH}\" \"${omero_web_id%%:*}\" \"${omero_web_id##*:}\" 755 \"Creating OMERO.web logs dir\"\n    ensure_directory \"${OMERO_WEB_SUPERVISOR_LOGS_PATH}\" \"${omero_web_id%%:*}\" \"${omero_web_id##*:}\" 755 \"Creating OMERO.web supervisor logs dir\"\n\n    # Shared / upload paths\n    ensure_directory \"${OMERO_UPLOAD_PATH}\" \"${omero_server_id%%:*}\" \"${omero_server_id##*:}\" 755 \"Creating Shared upload dir\"\n    # If the user sets different UIDs, make sure web can also access it if needed.\n    if [ \"${omero_server_id%%:*}\" != \"${omero_web_id%%:*}\" ]; then\n        chmod 777 \"${OMERO_UPLOAD_PATH}\"\n    fi\n    ensure_directory \"${OMERO_USER_DATA_PATH}\" \"${omero_server_id%%:*}\" \"${omero_server_id##*:}\" 755 \"Creating Shared user data dir\"\n    if [ \"${omero_server_id%%:*}\" != \"${omero_web_id%%:*}\" ]; then\n        chmod 777 \"${OMERO_USER_DATA_PATH}\"\n    fi\n\n    # Databases\n    ensure_directory \"${OMERO_DATABASE_PATH}\" \"${db_id%%:*}\" \"${db_id##*:}\" 700 \"Creating OMERO PostgreSQL dir\"\n    ensure_directory \"${OMERO_PLUGIN_DATABASE_PATH}\" \"${plugin_db_id%%:*}\" \"${plugin_db_id##*:}\" 700 \"Creating Plugin PostgreSQL dir\"\n    ensure_directory \"${PG_MAINTENANCE_DATA_PATH}\" \"${db_id%%:*}\" \"${db_id##*:}\" 755 \"Creating PG Maintenance dir\"\n\n    # Monitoring / Observability\n    ensure_directory \"${PROMETHEUS_DATA_PATH}\" \"${prometheus_id%%:*}\" \"${prometheus_id##*:}\" 755 \"Creating Prometheus data dir\"\n    ensure_directory \"${GRAFANA_DATA_PATH}\" \"${grafana_id%%:*}\" \"${grafana_id##*:}\" 755 \"Creating Grafana data dir\"\n    ensure_directory \"${LOKI_DATA_PATH}\" \"${loki_id%%:*}\" \"${loki_id##*:}\" 755 \"Creating Loki data dir\"\n    ensure_directory \"${NODE_EXPORTER_TEXTFILE_PATH}\" \"65534\" \"65534\" 755 \"Creating Node Exporter textfile dir\"\n\n    # Security\n    ensure_directory \"${CROWDSEC_DB_PATH}\" \"${crowdsec_id%%:*}\" \"${crowdsec_id##*:}\" 700 \"Creating CrowdSec DB dir\"\n    ensure_directory \"${CROWDSEC_CONFIG_PATH}\" \"${crowdsec_id%%:*}\" \"${crowdsec_id##*:}\" 700 \"Creating CrowdSec Config dir\"\n    \n    # Portainer - handled by Portainer itself usually, but ensure base path\n    if [ -n \"${PORTAINER_DATA_PATH}\" ]; then\n        ensure_directory \"${PORTAINER_DATA_PATH}\" \"0\" \"0\" 755 \"Creating Portainer data dir\"\n    fi\n}\n\nrestart_containers() {\n    if [ \"${START_CONTAINERS}\" = \"0\" ]; then\n        echo \"START_CONTAINERS=0; skipping docker compose up.\"\n        return 0\n    fi\n\n    echo \"Starting containers...\"\n    local attempt=1\n    while [ \"${attempt}\" -le \"${COMPOSE_UP_RETRIES}\" ]; do\n        if compose_with_installation_env \"${COMPOSE_FILE}\" up -d --remove-orphans; then\n            echo \"Containers started successfully.\"\n            return 0\n        fi\n        echo \"WARNING: docker compose up failed on attempt ${attempt}/${COMPOSE_UP_RETRIES}\" >&2\n        if [ \"${attempt}\" -lt \"${COMPOSE_UP_RETRIES}\" ]; then\n            echo \"Retrying in ${COMPOSE_UP_RETRY_DELAY_SECONDS} seconds...\"\n            sleep \"${COMPOSE_UP_RETRY_DELAY_SECONDS}\"\n        fi\n        attempt=$((attempt + 1))\n    done\n\n    echo \"ERROR: Failed to start containers after ${COMPOSE_UP_RETRIES} attempts.\" >&2\n    return 1\n}\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\nmain() {\n    echo \"==================================================\"\n    echo \" OMERO Extended - Installation / Update Script\"\n    echo \"==================================================\"\n    echo \"Mode: ${INSTALLATION_AUTOMATION_MODE:=0} (1=non-interactive)\"\n\n    # Validation\n    require_path_config_var \"OMERO_INSTALLATION_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_DATABASE_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_PLUGIN_DATABASE_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_DATA_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_USER_DATA_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_UPLOAD_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_SERVER_VAR_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_WEB_VAR_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_SERVER_LOGS_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_WEB_LOGS_PATH\" \"installation paths\"\n    require_path_config_var \"OMERO_WEB_SUPERVISOR_LOGS_PATH\" \"installation paths\"\n    require_path_config_var \"PORTAINER_DATA_PATH\" \"installation paths\"\n    require_path_config_var \"PROMETHEUS_DATA_PATH\" \"installation paths\"\n    require_path_config_var \"GRAFANA_DATA_PATH\" \"installation paths\"\n    require_path_config_var \"LOKI_DATA_PATH\" \"installation paths\"\n    require_path_config_var \"PG_MAINTENANCE_DATA_PATH\" \"installation paths\"\n    require_path_config_var \"BUILDX_DATA_PATH\" \"installation paths\"\n    require_path_config_var \"NODE_EXPORTER_TEXTFILE_PATH\" \"installation paths\"\n    require_path_config_var \"CROWDSEC_DB_PATH\" \"installation paths\"\n    require_path_config_var \"CROWDSEC_CONFIG_PATH\" \"installation paths\"\n\n    require_nonempty_config_var \"OMERO_DB_PASS\" \"secrets\"\n    require_nonempty_config_var \"OMP_PLUGIN_DB_PASS\" \"secrets\"\n\n    validate_retry_config\n    validate_toggle_config \"USE_CACHE_BUILD\" \"${USE_CACHE_BUILD}\"\n    validate_toggle_config \"USE_BUILDX_COMPRESSED_BUILD\" \"${USE_BUILDX_COMPRESSED_BUILD}\"\n    validate_toggle_config \"KEEP_IMAGES\" \"${KEEP_IMAGES}\"\n    validate_toggle_config \"START_CONTAINERS\" \"${START_CONTAINERS}\"\n    validate_toggle_config \"INSTALLATION_AUTOMATION_MODE\" \"${INSTALLATION_AUTOMATION_MODE}\"\n\n    COMPOSE_FILE=\"${OMERO_INSTALLATION_PATH%/}/docker-compose.yml\"\n    if [ ! -r \"${COMPOSE_FILE}\" ]; then\n        echo \"ERROR: Expected compose file missing or unreadable: ${COMPOSE_FILE}\" >&2\n        exit 1\n    fi\n\n    export_compose_interpolation_env\n\n    # Phase 1: Cleanup disabled cache (if applicable)\n    cleanup_local_build_cache_if_disabled\n\n    # Phase 2: Directory setup and permissions\n    setup_directories\n\n    # Phase 3: Build\n    if ! run_image_build; then\n        echo \"ERROR: Build phase failed.\" >&2\n        exit 1\n    fi\n\n    # Phase 4: Container restart\n    if ! restart_containers; then\n        exit 1\n    fi\n\n    # Phase 5: Prune old images (optional)\n    if [ \"${KEEP_IMAGES}\" = \"0\" ]; then\n        echo \"Pruning old docker images...\"\n        docker image prune -f >/dev/null 2>&1 || true\n    fi\n\n    echo \"\"\n    echo \"Installation/Update script completed successfully.\"\n}\n\nmain \"$@\"\n